def save_order(tenant: str, payload: dict[str, Any]) -> dict[str, Any]:
    tenant = safe_id(tenant)
    order_id = datetime.now(timezone.utc).strftime("ORD-%Y%m%d-%H%M%S-") + uuid.uuid4().hex[:8]
    items = payload.get("items") or []
    customer = payload.get("customer") or {}
    allowed_payment_methods = {"card", "bank_transfer", "cash_on_delivery"}
    allowed_countries = {"RO", "HU", "BG", "GR"}
    vat_rate = 0.19

    if not items:
        raise ValueError("empty_cart")

    cfg = tenant_config(tenant)
    idempiere = cfg.get("idempiere") if isinstance(cfg.get("idempiere"), dict) else {}
    stock_audit = idempiere.get("last_stock_audit") if isinstance(idempiere.get("last_stock_audit"), dict) else {}

    raw_catalog = catalog(tenant)
    product_index = {}
    for product in raw_catalog.get("products", []):
        for key in (product.get("id"), product.get("sku"), product.get("ean"), product.get("upc")):
            if key:
                product_index[str(key)] = product

    shipping_address = normalize_shipping_address(customer, payload.get("shipping_address"))
    if not customer.get("name") or not customer.get("phone") or not shipping_address.get("address") or not customer.get("email"):
        raise ValueError("missing_customer")

    customer_type = str(customer.get("customer_type") or "individual")
    if customer_type not in {"individual", "company"}:
        raise ValueError("invalid_customer_type")
    if customer_type == "company" and (not customer.get("company_name") or not customer.get("company_vat")):
        raise ValueError("missing_company")

    payment_method = str(customer.get("payment_method") or "")
    if payment_method not in allowed_payment_methods:
        raise ValueError("invalid_payment_method")

    country = str(shipping_address.get("country") or customer.get("country") or "RO").upper()
    customer["country"] = country
    customer["address"] = shipping_address.get("address") or str(customer.get("address") or "")
    if country not in allowed_countries:
        raise ValueError("unsupported_country")

    phone = str(customer.get("phone") or "")
    email = str(customer.get("email") or "").strip().lower()
    if not re.fullmatch(r"[+0-9 ()-]{7,24}", phone):
        raise ValueError("invalid_phone")
    if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email):
        raise ValueError("invalid_email")

    products_total_gross = 0.0
    normalized_items = []
    for item in items:
        qty = max(1, int(item.get("qty") or 1))
        lookup_keys = [str(item.get("id") or ""), str(item.get("sku") or ""), str(item.get("ean") or "")]
        product = next((product_index[k] for k in lookup_keys if k and k in product_index), None)
        if not product:
            raise ValueError("unknown_product")
        sku = str(product.get("sku") or "")
        if not sku:
            raise ValueError("product_missing_sku")
        price = round(float(product.get("price_ron") or product.get("price") or 0), 2)
        if price < 0:
            raise ValueError("invalid_price")
        products_total_gross += qty * price
        normalized_items.append({
            "id": str(product.get("id") or ""),
            "sku": sku,
            "ean": str(product.get("ean") or product.get("upc") or ""),
            "name": str(product.get("name") if not isinstance(product.get("name"), dict) else (product.get("name", {}).get("ro") or "")),
            "price_gross_ron": price,
            "price_gross": price,
            "price": price,
            "currency": "RON",
            "qty": qty,
            "line_total_gross": round(qty * price, 2),
            "url": str(product.get("url") or ""),
            "image": str(product.get("image") or ""),
        })

    order_stock_check = stock_mapping_check(cfg, [item["sku"] for item in normalized_items])
    stock_mapping_ready = bool(order_stock_check["ready"])

    rates = currency_rates.get_rates()
    display_currency = currency_rates.currency_for_country(country)
    shipping_total_ron = 29.99 if country == "RO" else 49.99
    products_total_gross_ron = round(products_total_gross, 2)
    products_total_net_ron = round(products_total_gross_ron / (1 + vat_rate), 2)
    vat_total_ron = round(products_total_gross_ron - products_total_net_ron, 2)
    invoice_total_ron = round(products_total_gross_ron + shipping_total_ron, 2)
    currency = display_currency
    products_total_gross = currency_rates.convert_from_ron(products_total_gross_ron, currency, rates)
    products_total_net = currency_rates.convert_from_ron(products_total_net_ron, currency, rates)
    vat_total = currency_rates.convert_from_ron(vat_total_ron, currency, rates)
    shipping_total = currency_rates.convert_from_ron(shipping_total_ron, currency, rates)
    invoice_total = currency_rates.convert_from_ron(invoice_total_ron, currency, rates)

    account = ensure_customer_account(tenant, {**customer, "email": email, "customer_type": customer_type}, shipping_address)
    seller = seller_identity(cfg)
    lang = str(payload.get("lang") or customer.get("lang") or DEFAULT_LANG)
    email_status = queue_account_email(
        tenant,
        order_id,
        {**customer, "email": email},
        account.get("initial_password", ""),
        seller.get("public_name", ""),
        lang if lang in LANGS else DEFAULT_LANG,
    )

    order = {
        "id": order_id,
        "tenant": tenant,
        "status": "new" if stock_mapping_ready else "pending_stock_mapping",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "customer": {
            "customer_type": customer_type,
            "name": str(customer.get("name") or ""),
            "phone": phone,
            "email": email,
            "country": country,
            "address": str(customer.get("address") or ""),
            "shipping_address_id": shipping_address.get("id"),
            "company_name": str(customer.get("company_name") or ""),
            "company_vat": str(customer.get("company_vat") or ""),
