        tenant = request_tenant()
        ip = request.headers.get("CF-Connecting-IP") or request.headers.get("X-Forwarded-For", "").split(",")[0] or request.remote_addr or "unknown"
        now = time.time()
        bucket = ORDER_RATE[ip]
        while bucket and now - bucket[0] > 600:
            bucket.popleft()
        if len(bucket) >= 5:
            return jsonify({"status": "error", "error": "rate_limited"}), 429
        payload = request.get_json(force=True)
        customer_payload = payload.get("customer") or {}
        if payload.get("website") or customer_payload.get("website"):
            return jsonify({"status": "error", "error": "spam_detected"}), 400
        try:
            result = cms.save_order(tenant, payload)
        except ValueError as exc:
            return jsonify({"status": "error", "error": str(exc)}), 400
        bucket.append(now)
        return jsonify(result)

