        long min = Long.MAX_VALUE;
        for (Map.Entry<Integer, BigDecimal> e : nevoie.entrySet()) {
            BigDecimal d = dispComponente == null ? null : dispComponente.get(e.getKey());
            if (d == null || d.signum() <= 0 || e.getValue().signum() <= 0)
                return 0;
            min = Math.min(min, d.divide(e.getValue(), 0, RoundingMode.FLOOR).longValueExact());
        }
        return Math.max(0, min);
    }

