    /** Un pas al regulii (pentru «Detaliu articol…»): codul pasului, valoarea înainte și după. */
    public record PasRegula(String pas, BigDecimal inainte, BigDecimal dupa) { }

    private static final int SCALA = 4;
    private static final BigDecimal O_SUTA = BigDecimal.valueOf(100);
    private static final Pattern ZECIMAL = Pattern.compile("[+-]?([0-9]+(\\.[0-9]*)?|\\.[0-9]+)");

    private RegulaStocCanal() { }

    /** Cantitatea oferită canalului; 0 ≤ rezultat ≤ max(0, stocCalculat). Regulă invalidă ⇒ 0 (siguranța: nu oferi mai mult decât ai). */
    public static long cantitateOferita(long stocCalculat, Map<String, String> reguli) {
        List<PasRegula> pasi = pasiRegula(stocCalculat, reguli);
        return pasi.get(pasi.size() - 1).dupa().longValueExact();
    }

    /** Aceeași calculare, pas cu pas (CALCULAT, REZERVA, REZERVAT_ALTE, PROCENT, PRAG, MAXIM, ROTUNJIRE) sau [REGULA_INVALIDA]. */
    public static List<PasRegula> pasiRegula(long stocCalculat, Map<String, String> reguli) {
        BigDecimal v0 = BigDecimal.valueOf(Math.max(0L, stocCalculat));
        if (refuzRegula(reguli) != null)
            return List.of(new PasRegula("REGULA_INVALIDA", v0, BigDecimal.ZERO));
        BigDecimal rezerva = intreg(valoare(reguli, REZERVA), BigDecimal.ZERO);
        BigDecimal rezervatAlte = intreg(valoare(reguli, REZERVAT_ALTE), BigDecimal.ZERO);
        String p = valoare(reguli, PROCENT);
        BigDecimal procent = p == null ? O_SUTA : new BigDecimal(p);
        BigDecimal prag = intreg(valoare(reguli, PRAG), BigDecimal.ZERO);
        String m = valoare(reguli, MAXIM);
        String r = valoare(reguli, ROTUNJIRE);
        boolean jos = r == null || "JOS".equals(r);   // codurile ROTUNJIRE_STOC (L2, DomeniiT35): JOS / NORMAL

        BigDecimal v1a = v0.subtract(rezerva).max(BigDecimal.ZERO);
        BigDecimal v1 = v1a.subtract(rezervatAlte).max(BigDecimal.ZERO);
        // v1 întreg, procentul are cel mult 2 zecimale ⇒ produsul / 100 are cel mult 4 zecimale: setScale(4) e exact, fără rotunjire
        BigDecimal v2 = v1.multiply(procent).divide(O_SUTA).setScale(SCALA);
        BigDecimal v3 = v2.compareTo(prag) < 0 ? BigDecimal.ZERO.setScale(SCALA) : v2;
        BigDecimal v4 = m == null ? v3 : v3.min(intreg(m, BigDecimal.ZERO).setScale(SCALA));
        BigDecimal v5 = v4.setScale(0, jos ? RoundingMode.FLOOR : RoundingMode.HALF_UP);
        return List.of(new PasRegula("CALCULAT", v0, v0),
                new PasRegula("REZERVA", v0, v1a),
                new PasRegula("REZERVAT_ALTE", v1a, v1),
                new PasRegula("PROCENT", v1, v2),
                new PasRegula("PRAG", v2, v3),
                new PasRegula("MAXIM", v3, v4),
                new PasRegula("ROTUNJIRE", v4, v5));
    }

    /** Cheia refuzului primei valori invalide (ordinea REZERVA, REZERVAT_ALTE, PROCENT, PRAG, MAXIM, ROTUNJIRE) sau null. */
    public static String refuzRegula(Map<String, String> reguli) {
        if (!intregNenegativ(valoare(reguli, REZERVA))) return "stoc.canal.regula.rezerva";
        if (!intregNenegativ(valoare(reguli, REZERVAT_ALTE))) return "stoc.canal.regula.rezervat_alte";
        String p = valoare(reguli, PROCENT);
        if (p != null) {
            BigDecimal x = numar(p);
            if (x == null || x.signum() < 0 || x.compareTo(O_SUTA) > 0 || x.stripTrailingZeros().scale() > 2)
                return "stoc.canal.regula.procent";
        }
        if (!intregNenegativ(valoare(reguli, PRAG))) return "stoc.canal.regula.prag";
        if (!intregNenegativ(valoare(reguli, MAXIM))) return "stoc.canal.regula.maxim";
        String r = valoare(reguli, ROTUNJIRE);
        if (r != null && !"JOS".equals(r) && !"NORMAL".equals(r)) return "stoc.canal.regula.rotunjire";
        return null;
    }

    /** Descărcarea ar lăsa stocul negativ (pur): {@code qtyOnHand − cantitate < 0}. */
    public static boolean lasaNegativ(BigDecimal qtyOnHand, BigDecimal cantitate) {
        BigDecimal q = qtyOnHand == null ? BigDecimal.ZERO : qtyOnHand;
        BigDecimal c = cantitate == null ? BigDecimal.ZERO : cantitate;
        return q.subtract(c).signum() < 0;
    }

    /**
     * Alocarea în ordinea sosirii (pură): fiecare linie, în ordinea dată, primește {@code REZERVAT} dacă disponibilul
     * gestiunii ei îl acoperă (disponibilul scade), altfel {@code ROSU}. Cu {@code gestiune = 0}, linia e servită INTEGRAL
     * dintr-o singură gestiune — prima, după id, cu disponibil suficient — altfel {@code ROSU} (Q-74m-5). Harta
     * {@code disponibil} se modifică (copia apelantului).
     */
    public static Map<Integer, String> aloca(List<LinieCerere> inOrdine, Map<String, BigDecimal> disponibil) {
        Map<Integer, String> r = new LinkedHashMap<>();
        for (LinieCerere l : inOrdine) {
            String k = l.gestiune() > 0 ? cheie(l.produs(), l.gestiune()) : primaGestiune(l, disponibil);
            if (k != null && acopera(l.cantitate(), disponibil.get(k))) {
                disponibil.put(k, disponibil.get(k).subtract(l.cantitate()));
                r.put(l.idLinie(), DomeniiT22.REZERVAT);
            } else
                r.put(l.idLinie(), DomeniiT22.ROSU);
        }
        return r;
    }

    private static String primaGestiune(LinieCerere l, Map<String, BigDecimal> disponibil) {
        TreeMap<Integer, String> g = new TreeMap<>();
        String pref = l.produs() + "|";
        for (String k : disponibil.keySet())
            if (k.startsWith(pref))
                g.put(Integer.parseInt(k.substring(pref.length())), k);
        for (String k : g.values())
            if (acopera(l.cantitate(), disponibil.get(k)))
                return k;
        return null;
    }

    /**
     * Garda STOC NEGATIV pe un VAL (pură; 75m D-2): liniile valului, în ordine, cumulate pe (articol, gestiune) față de
     * stocul fizic citit sub blocare; o linie care ar duce suma peste stoc e refuzată (ROȘIE) și NU se cumulează, deci stocul
     * nu ajunge niciodată sub 0. Întoarce id-urile liniilor refuzate.
     * P01.T354 A (R7 / R22): cererile se grupează pe linie ({@code idLinie}, în ordinea primei apariții) — setul are câte o cerere pe
     * componentă; linia e refuzată dacă ORICARE dintre cererile ei ar lăsa stocul negativ și atunci NICIO cerere a ei nu se cumulează
     * (setul ROȘU își eliberează cererea). Pe grupuri de câte o cerere (articolul obișnuit) rezultatul e cel de dinainte (TestT354Set §13,
     * 300 de valuri aleatoare față de forma veche).
     */
    public static Set<Integer> liniiPesteStoc(List<LinieCerere> val, Map<String, BigDecimal> stocFizic) {
        Map<Integer, List<LinieCerere>> grupuri = new LinkedHashMap<>();
        for (LinieCerere l : val)
            grupuri.computeIfAbsent(l.idLinie(), k -> new ArrayList<>()).add(l);
        Map<String, BigDecimal> folosit = new LinkedHashMap<>();
        Set<Integer> refuzate = new LinkedHashSet<>();
        for (Map.Entry<Integer, List<LinieCerere>> g : grupuri.entrySet()) {
            Map<String, BigDecimal> proba = new LinkedHashMap<>(folosit);
            boolean refuz = false;
            for (LinieCerere l : g.getValue()) {
                String k = cheie(l.produs(), l.gestiune());
                BigDecimal suma = proba.getOrDefault(k, BigDecimal.ZERO).add(l.cantitate());
                if (lasaNegativ(stocFizic.get(k), suma))
                    refuz = true;
                proba.put(k, suma);
            }
            if (refuz)
                refuzate.add(g.getKey());
            else
                folosit = proba;
        }
        return refuzate;
    }

